using System.Collections.Concurrent;
using System.Globalization;
using System.Text;

namespace Autheris.Application.Data.Services;

/// <summary>
/// #326 GAP-035: SQLite has no time-zone data, so a zone-aware bucket needs the UTC offset per instant. The offsets come from
/// the zone's UTC transitions (years <see cref="FirstYear"/> to <see cref="LastYear"/>), are generated by the server from an
/// allowlisted zone only (SEC-RG-12) and are emitted as fixed-shape literals (invariant culture, no caller text). Outside the
/// year range the zone's base offset applies (documented limit). The table is built once per zone and cached; it is bounded by
/// the zone count of the allowlist times the year range.
/// </summary>
internal static class SqliteZoneOffsetTable
{
    public const int FirstYear = 1970;
    public const int LastYear = 2099;

    private const string InstantFormat = "yyyy-MM-dd HH:mm:ss";

    private static readonly ConcurrentDictionary<string, ZoneArms> Cache = new(StringComparer.OrdinalIgnoreCase);

    /// <summary>One interval [FromUtc, ToUtc) in which the offset differs from the base offset.</summary>
    internal sealed record Arm(string FromUtc, string ToUtc, string Offset);

    internal sealed record ZoneArms(string BaseOffset, IReadOnlyList<Arm> Arms);

    /// <summary>
    /// The SQLite modifier expression for the offset of <paramref name="utcExpression"/> (a UTC <c>datetime(...)</c> text expression) in the
    /// zone: a literal such as <c>'+05:30'</c> for a zone without transitions, otherwise a <c>CASE</c> over the transition arms.
    /// </summary>
    public static string OffsetModifier(string zoneId, string utcExpression)
    {
        var table = Get(zoneId);
        if (table.Arms.Count == 0)
        {
            return $"'{table.BaseOffset}'";
        }

        var sb = new StringBuilder("CASE");
        foreach (var arm in table.Arms)
        {
            sb.Append(" WHEN ").Append(utcExpression).Append(" >= '").Append(arm.FromUtc)
                .Append("' AND ").Append(utcExpression).Append(" < '").Append(arm.ToUtc)
                .Append("' THEN '").Append(arm.Offset).Append('\'');
        }

        return sb.Append(" ELSE '").Append(table.BaseOffset).Append("' END").ToString();
    }

    internal static ZoneArms Get(string zoneId)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(zoneId);

        // SEC-RG-12: only allowlisted zones; anything else fails closed exactly as before.
        if (!TrinoSqlEngine.TimeZoneRegistry.Contains(zoneId))
        {
            throw new ArgumentException($"Time zone '{zoneId}' is not recognized.");
        }

        return Cache.GetOrAdd(zoneId, Build);
    }

    private static ZoneArms Build(string zoneId)
    {
        TimeZoneInfo zone;
        try
        {
            zone = TimeZoneInfo.FindSystemTimeZoneById(zoneId);
        }
        catch (Exception ex) when (ex is TimeZoneNotFoundException or InvalidTimeZoneException)
        {
            throw new ArgumentException($"Time zone '{zoneId}' is not available on this host.");
        }

        var baseOffset = zone.BaseUtcOffset;
        var start = new DateTimeOffset(FirstYear, 1, 1, 0, 0, 0, TimeSpan.Zero);
        var end = new DateTimeOffset(LastYear + 1, 1, 1, 0, 0, 0, TimeSpan.Zero);

        var arms = new List<Arm>();
        var current = zone.GetUtcOffset(start);
        var armStart = current == baseOffset ? (DateTimeOffset?)null : start;

        for (var day = start.AddDays(1); day <= end; day = day.AddDays(1))
        {
            var offset = zone.GetUtcOffset(day);
            if (offset == current)
            {
                continue;
            }

            var transition = FindTransition(zone, day.AddDays(-1), day, current);
            if (armStart is { } open)
            {
                arms.Add(new Arm(Format(open), Format(transition), FormatOffset(current)));
            }

            armStart = offset == baseOffset ? null : transition;
            current = offset;
        }

        if (armStart is { } last)
        {
            arms.Add(new Arm(Format(last), Format(end), FormatOffset(current)));
        }

        return new ZoneArms(FormatOffset(baseOffset), arms);
    }

    /// <summary>First whole second in (<paramref name="low"/>, <paramref name="high"/>] whose offset differs from <paramref name="before"/>.</summary>
    private static DateTimeOffset FindTransition(TimeZoneInfo zone, DateTimeOffset low, DateTimeOffset high, TimeSpan before)
    {
        long lo = low.ToUnixTimeSeconds();
        long hi = high.ToUnixTimeSeconds();
        while (hi - lo > 1)
        {
            long mid = lo + ((hi - lo) / 2);
            if (zone.GetUtcOffset(DateTimeOffset.FromUnixTimeSeconds(mid)) == before)
            {
                lo = mid;
            }
            else
            {
                hi = mid;
            }
        }

        return DateTimeOffset.FromUnixTimeSeconds(hi);
    }

    private static string Format(DateTimeOffset utc) => utc.UtcDateTime.ToString(InstantFormat, CultureInfo.InvariantCulture);

    private static string FormatOffset(TimeSpan offset) =>
        (offset < TimeSpan.Zero ? "-" : "+") + offset.Duration().ToString(@"hh\:mm", CultureInfo.InvariantCulture);
}
